-- Empty disposable database only. Contains synthetic identities; never production.
\set ON_ERROR_STOP on
DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon; END IF; IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated; END IF; IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role BYPASSRLS; END IF; END $$;
CREATE SCHEMA auth;
GRANT USAGE ON SCHEMA auth TO authenticated,service_role;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid $$;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE TABLE public.user_memory(user_id uuid REFERENCES auth.users ON DELETE CASCADE,key text,memory_kind text,payload jsonb,PRIMARY KEY(user_id,key));
CREATE TABLE public.app_inventories(inventory_id uuid PRIMARY KEY);
CREATE TABLE public.test_grants(user_id uuid,inventory_id uuid,role text);
CREATE FUNCTION public.findez_inventory_role(i uuid,u uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT role FROM public.test_grants WHERE user_id=u AND inventory_id=i $$;
CREATE FUNCTION public.findez_request_actor() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT auth.uid() $$;
CREATE TABLE public.items(item_id uuid PRIMARY KEY,inventory_id uuid REFERENCES public.app_inventories,user_id uuid REFERENCES auth.users ON DELETE CASCADE,name text,quantity int,location text,space_id uuid,updated_at timestamptz,reorder_enabled boolean DEFAULT false,reorder_threshold int);
CREATE TABLE public.capture_reviews(review_id uuid PRIMARY KEY,inventory_id uuid REFERENCES public.app_inventories,user_id uuid REFERENCES auth.users ON DELETE CASCADE,status text);
CREATE TABLE public.push_devices(device_token text PRIMARY KEY,user_id uuid REFERENCES auth.users ON DELETE CASCADE,environment text,enabled bool,updated_at timestamptz);
INSERT INTO auth.users VALUES('10000000-0000-0000-0000-000000000001'),('10000000-0000-0000-0000-000000000002');
INSERT INTO public.app_inventories VALUES('20000000-0000-0000-0000-000000000001'),('20000000-0000-0000-0000-000000000002');
INSERT INTO public.test_grants SELECT id,'20000000-0000-0000-0000-000000000001','editor' FROM auth.users;
INSERT INTO public.user_memory SELECT id,'__settings_v1','settings','{"enabled":true,"generation":0}' FROM auth.users;
\ir ../../supabase/migrations/081_personalization_engine.sql
CREATE FUNCTION pg_temp.check(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; RAISE NOTICE 'PASS: %',label; END $$;
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001"}',false);
SELECT pg_temp.check(NOT public.findez_personalization_enabled(auth.uid()),'cold start is disabled');
SELECT public.findez_personalization_change(auth.uid(),'40000000-0000-0000-0000-000000000001',repeat('a',64),0,'settings','{"enabled":true,"categories":["low_stock","scan_review"],"timezone":"UTC","quiet_start":0,"quiet_end":1,"daily_cap":1,"weekly_cap":3}');
SELECT public.findez_personalization_change(auth.uid(),'40000000-0000-0000-0000-000000000001',repeat('a',64),0,'settings','{"enabled":true,"categories":["low_stock","scan_review"],"timezone":"UTC","quiet_start":0,"quiet_end":1,"daily_cap":1,"weekly_cap":3}');
SELECT pg_temp.check((SELECT revision=1 FROM public.personalization_profiles WHERE user_id=auth.uid()),'retry does not increment revision');
INSERT INTO public.items VALUES('30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001',auth.uid(),'Screws',10,'Drawer',null,now(),true,2);
SELECT pg_temp.check((SELECT count(*)=1 FROM public.personalization_events WHERE event_type='inventory.item_created'),'actual insert records event');
DO $$ BEGIN
 BEGIN PERFORM public.findez_personalization_event(auth.uid(),0,'bad','inventory.search_failed',NULL,NULL,NULL,'{"count":"not a count"}'); RAISE EXCEPTION 'bad payload accepted'; EXCEPTION WHEN check_violation OR invalid_text_representation THEN RAISE NOTICE 'PASS: database rejects malformed event payload'; END;
END $$;
UPDATE public.items SET updated_at=now();
SELECT pg_temp.check((SELECT count(*)=1 FROM public.personalization_events),'no-op retry creates no event');
SELECT public.findez_personalization_change(auth.uid(),'40000000-0000-0000-0000-000000000002',repeat('b',64),1,'alias','{"inventory_id":"20000000-0000-0000-0000-000000000001","alias":"my fasteners","item_id":"30000000-0000-0000-0000-000000000001"}');
SELECT pg_temp.check(jsonb_array_length(public.findez_personalization_context(auth.uid(),'20000000-0000-0000-0000-000000000001')->'aliases')=1,'confirmed alias retrieval');
DO $$ BEGIN
 BEGIN PERFORM public.findez_personalization_change(auth.uid(),gen_random_uuid(),repeat('c',64),1,'reset','{}'); RAISE EXCEPTION 'accepted stale'; EXCEPTION WHEN serialization_failure THEN RAISE NOTICE 'PASS: stale revision rejected'; END;
 BEGIN PERFORM public.findez_personalization_change(auth.uid(),gen_random_uuid(),repeat('c',64),2,'alias','{"inventory_id":"20000000-0000-0000-0000-000000000002","alias":"foreign","item_id":"30000000-0000-0000-0000-000000000001"}'); RAISE EXCEPTION 'accepted foreign'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS: unauthorized target rejected'; END;
END $$;
UPDATE public.items SET quantity=-1;
SELECT pg_temp.check((SELECT count(*)=0 FROM public.personalization_notifications),'unknown quantity is not low stock');
UPDATE public.items SET quantity=10;
UPDATE public.items SET quantity=2;
SELECT pg_temp.check((SELECT count(*)=1 FROM public.personalization_notifications),'verified threshold crossing produces one candidate');
UPDATE public.items SET quantity=2;
SELECT pg_temp.check((SELECT count(*)=1 FROM public.personalization_notifications),'duplicate update has no second candidate');
SELECT pg_temp.check(public.findez_personalization_claim((SELECT id FROM public.personalization_notifications LIMIT 1)) IS NULL,'no registered device means no send');
INSERT INTO public.push_devices VALUES('test',auth.uid(),'sandbox',true,now(),true);
-- Keep tests independent of execution hour; zero-width quiet hours is quiet all day.
UPDATE public.personalization_profiles SET quiet_start=0,quiet_end=0;
SELECT pg_temp.check(public.findez_personalization_claim((SELECT id FROM public.personalization_notifications LIMIT 1)) IS NULL,'quiet hours enforced');
UPDATE public.personalization_profiles SET quiet_start=(extract(hour from now() AT TIME ZONE 'UTC')::int*60+extract(minute from now() AT TIME ZONE 'UTC')::int+60)%1440,quiet_end=(extract(hour from now() AT TIME ZONE 'UTC')::int*60+extract(minute from now() AT TIME ZONE 'UTC')::int+61)%1440;
SELECT pg_temp.check(jsonb_array_length(public.findez_personalization_candidates(50))=1,'ranked candidate query is bounded');
SELECT pg_temp.check(public.findez_personalization_claim((SELECT id FROM public.personalization_notifications LIMIT 1)) IS NOT NULL,'eligible candidate claimed');
SELECT pg_temp.check(public.findez_personalization_delivery_ready((SELECT id FROM public.personalization_notifications LIMIT 1)),'eligibility rechecked before delivery');
UPDATE public.personalization_profiles SET categories='{}';
SELECT pg_temp.check(NOT public.findez_personalization_delivery_ready((SELECT id FROM public.personalization_notifications LIMIT 1)),'late category opt-out blocks delivery');
UPDATE public.personalization_profiles SET categories=ARRAY['low_stock','scan_review'];
SELECT pg_temp.check(public.findez_personalization_claim((SELECT id FROM public.personalization_notifications LIMIT 1)) IS NULL,'duplicate claim suppressed');
UPDATE public.personalization_notifications SET state='accepted',accepted_at=now();
SELECT pg_temp.check((SELECT delivered_at IS NULL AND opened_at IS NULL FROM public.personalization_notifications LIMIT 1),'APNs acceptance is not delivery or open');
SELECT public.findez_personalization_feedback(auth.uid(),(SELECT id FROM public.personalization_notifications LIMIT 1),'opened');
SELECT public.findez_personalization_feedback(auth.uid(),(SELECT id FROM public.personalization_notifications LIMIT 1),'opened');
SELECT pg_temp.check((SELECT count(*)=1 FROM public.personalization_events WHERE event_type='notification.opened'),'open feedback idempotent');
SELECT pg_temp.check((SELECT count(*)=0 FROM public.personalization_events WHERE event_type='notification.action_completed'),'open is not completion');
UPDATE public.items SET quantity=10;
SELECT pg_temp.check((SELECT count(*)=1 FROM public.personalization_events WHERE event_type='notification.action_completed'),'verified replenishment after open is useful outcome');
UPDATE public.items SET quantity=1;
SELECT pg_temp.check(public.findez_personalization_claim((SELECT id FROM public.personalization_notifications WHERE state='pending' LIMIT 1)) IS NULL,'rolling frequency cap enforced');
SELECT pg_temp.check(public.findez_personalization_destination('10000000-0000-0000-0000-000000000002',(SELECT id FROM public.personalization_notifications LIMIT 1)) IS NULL,'notification ownership required even within shared inventory');
INSERT INTO public.capture_reviews VALUES('50000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001',auth.uid(),'pending');
SELECT pg_temp.check((SELECT count(*)=1 FROM public.personalization_notifications WHERE category='scan_review'),'review candidate exists');
UPDATE public.capture_reviews SET status='resolved';
SELECT pg_temp.check((SELECT state='resolved' FROM public.personalization_notifications WHERE category='scan_review'),'resolved review suppressed');
SET ROLE authenticated;
SELECT pg_temp.check((SELECT count(*)=1 FROM public.personalization_profiles),'own profile visible');
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000002"}',false);
SELECT pg_temp.check((SELECT count(*)=0 FROM public.personalization_profiles),'other profile hidden');
SELECT pg_temp.check((SELECT count(*)=0 FROM public.personalization_events),'other events hidden');
SELECT pg_temp.check((SELECT count(*)=0 FROM public.personalization_aliases),'other aliases hidden');
DO $$ BEGIN
 BEGIN PERFORM public.findez_personalization_context('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001'); RAISE EXCEPTION 'client rpc accepted'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS: client cannot impersonate actor'; END;
 BEGIN INSERT INTO public.personalization_profiles(user_id) VALUES(auth.uid()); RAISE EXCEPTION 'client write accepted'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS: direct writes denied'; END;
END $$;
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001"}',false);
DELETE FROM public.test_grants WHERE user_id=auth.uid();
SELECT pg_temp.check(public.findez_personalization_context(auth.uid(),'20000000-0000-0000-0000-000000000001') IS NULL,'revoked inventory context denied');
SELECT pg_temp.check(public.findez_personalization_destination(auth.uid(),(SELECT id FROM public.personalization_notifications LIMIT 1)) IS NULL,'revoked destination denied');
UPDATE public.user_memory SET payload='{"enabled":false,"generation":1}' WHERE user_id=auth.uid();
SELECT pg_temp.check((SELECT count(*)=0 FROM public.personalization_events),'master Forget clears events');
SELECT pg_temp.check((SELECT count(*)=0 FROM public.personalization_aliases),'master Forget clears aliases');
SELECT pg_temp.check((SELECT count(*)=0 FROM public.personalization_notifications),'master Forget clears notifications');
SELECT pg_temp.check(NOT public.findez_personalization_event(auth.uid(),0,'late','inventory.search_failed',NULL,NULL,NULL,'{}'),'old queued work cannot resurrect');
DELETE FROM auth.users WHERE id=auth.uid();
SELECT pg_temp.check((SELECT count(*)=0 FROM public.personalization_profiles),'account deletion cascades');
SELECT pg_temp.check((SELECT count(*)=0 FROM public.personalization_receipts),'account deletion clears receipts');
